pa.append(t(170 + 4 * u + 14, 113, '+$4,00', 'mint', 20, 'start', 800))
pa.append(t(30, 192, '5 програшів', 'rose', 18))
for i in range(5):
    x = 170 + i * u; pa.append(rect(x + 2, 162, u - 4, 48, 'rose', .25, rx=8)); pa.append(t(x + u / 2, 192, '−1,00', 'rose', 16, 'middle'))
pa.append(t(170 + 5 * u + 14, 193, '−$5,00', 'rose', 20, 'start', 800))
pa.append(line(170 + 4 * u, 70, 170 + 4 * u, 222, 'amber', 2, '5 4'))
